functions.supplier_submit_quote(text,numeric,text,:
CREATE OR REPLACE FUNCTION public.supplier_submit_quote(p_request_code text, p_total_amount numeric, p_estimated_time text DEFAULT NULL::text, p_availability text DEFAULT NULL::text, p_allowed_public_notes text DEFAULT NULL::text, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS quotes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_campaign public.campaigns%rowtype;
  v_quote public.quotes%rowtype;
begin
  if v_uid is null then raise exception 'NON_AUTENTICATO' using errcode = '42501'; end if;
  if not public.is_verified_supplier(v_uid) then
    raise exception 'FORNITORE_NON_VERIFICATO' using errcode = '42501';
  end if;
  if p_total_amount is null or p_total_amount <= 0 then
    raise exception 'IMPORTO_NON_VALIDO' using errcode = '22023';
  end if;

  select * into v_campaign from public.campaigns
    where marketplace_code = p_request_code for update;
  if not found then raise exception 'RICHIESTA_NON_TROVATA' using errcode = 'P0002'; end if;
  if v_campaign.status not in ('requested', 'receiving_quotes') or v_campaign.supplier_id is not null then
    raise exception 'RICHIESTA_NON_DISPONIBILE' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.quotes q
    where q.campaign_id = v_campaign.id and q.supplier_id = v_uid and q.quote_status = 'submitted'
  ) then
    raise exception 'OFFERTA_GIA_INVIATA' using errcode = '23505';
  end if;

  perform set_config('marketplace.rpc', 'on', true);
  begin
    insert into public.quotes
      (campaign_id, supplier_id, quote_status, subtotal, total_amount, currency,
       estimated_time, availability, allowed_public_notes, valid_until, submitted_at)
    values
      (v_campaign.id, v_uid, 'submitted', p_total_amount, p_total_amount, 'EUR',
       nullif(btrim(p_estimated_time), ''), nullif(btrim(p_availability), ''),
       nullif(btrim(p_allowed_public_notes), ''), p_valid_until, now())
    returning * into v_quote;
  exception when unique_violation then
    -- Concorrenza: due submit dello STESSO Supplier passano entrambi il
    -- controllo `if exists` sopra, poi uno viola
    -- quotes_marketplace_one_submitted_per_supplier. Semantica coerente,
    -- mai un raw 23505 al client.
    raise exception 'OFFERTA_GIA_INVIATA' using errcode = '23505';
  end;

  if v_campaign.status = 'requested' then
    update public.campaigns set status = 'receiving_quotes' where id = v_campaign.id;
  end if;

  return v_quote;
end;
$function$

functions.admin_log_campaign_action(uuid,text,text:
CREATE OR REPLACE FUNCTION public.admin_log_campaign_action(p_campaign_id uuid, p_action text, p_previous_state text, p_new_state text, p_reason text)
 RETURNS campaign_admin_action_log
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_title text;
  v_row public.campaign_admin_action_log%rowtype;
begin
  if not public.gps_is_admin() then
    raise exception 'ADMIN_NON_AUTORIZZATO' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'MOTIVO_OBBLIGATORIO' using errcode = '22023';
  end if;

  select title into v_title from public.campaigns where id = p_campaign_id;
  if v_title is null then
    raise exception 'CAMPAGNA_NON_TROVATA' using errcode = 'P0002';
  end if;

  insert into public.campaign_admin_action_log (
    campaign_id, campaign_id_snapshot, campaign_title_snapshot,
    action, previous_state, new_state, reason, actor_id
  ) values (
    p_campaign_id, p_campaign_id, v_title,
    p_action, p_previous_state, p_new_state, btrim(p_reason), v_uid
  )
  returning * into v_row;

  return v_row;
end;
$function$

functions.protect_campaign_admin_action_log_snapsh:
CREATE OR REPLACE FUNCTION public.protect_campaign_admin_action_log_snapshots()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.campaign_id_snapshot is distinct from old.campaign_id_snapshot
     or new.campaign_title_snapshot is distinct from old.campaign_title_snapshot then
    raise exception 'SNAPSHOT_STORICO_IMMUTABILE' using errcode = '23000';
  end if;
  return new;
end;
$function$

functions.quotes_marketplace_guard():
CREATE OR REPLACE FUNCTION public.quotes_marketplace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rpc text := current_setting('marketplace.rpc', true);
  v_admin boolean := public.jwt_is_admin();
begin
  if tg_op = 'INSERT' then
    if new.supplier_id is not null and coalesce(v_rpc, '') <> 'on' and not v_admin then
      raise exception 'QUOTE_MARKETPLACE_RPC_ONLY' using errcode = '42501';
    end if;
    return new;
  end if;
  if old.supplier_id is not null then
    if (new.quote_status is distinct from old.quote_status
        or new.supplier_id is distinct from old.supplier_id
        or new.total_amount is distinct from old.total_amount
        or new.subtotal is distinct from old.subtotal)
       and coalesce(v_rpc, '') <> 'on' and not v_admin then
      raise exception 'QUOTE_MARKETPLACE_RPC_ONLY' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$function$
